(()=>{'use strict';const $=(s,r=document)=>r.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:window.MAKHRAJ_CONFIG?.currency||'USD'}).format(Number(n||0));async function load(){const host=$('#solutionBundles');if(!host)return;try{const cfg=window.MAKHRAJ_CONFIG,sb=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseKey);const {data,error}=await sb.from('solution_bundles').select('id,title,summary,need_query,need_tags,situation_tags,solution_bundle_items(quantity,is_required,reason,products(id,name,base_price,product_images(url,sort_order),product_variants(id,price,stock_quantity)))').eq('status','active').order('sort_order').limit(8);if(error)throw error;if(!data?.length){host.classList.add('hidden');return}host.classList.remove('hidden');$('#bundleRail').innerHTML=data.map(b=>{const items=b.solution_bundle_items||[],available=items.filter(i=>(i.products?.product_variants||[]).some(v=>Number(v.stock_quantity)>0)),total=available.reduce((s,i)=>{const p=i.products,prices=(p?.product_variants||[]).filter(v=>v.stock_quantity>0).map(v=>Number(v.price??p.base_price));return s+(prices.length?Math.min(...prices):Number(p?.base_price||0))*i.quantity},0);return '<article class="card bundle-card"><div class="tiny">مَخْرَج مركّب · '+items.length+' عناصر</div><h3>'+esc(b.title)+'</h3><p class="muted">'+esc(b.summary||b.need_query||'حل متكامل لحاجة محددة')+'</p><div class="bundle-items">'+items.slice(0,4).map(i=>'<span>'+esc(i.products?.name||'عنصر')+(i.quantity>1?' ×'+i.quantity:'')+'</span>').join('')+'</div><div class="line"><b class="price">'+money(total)+'</b><span class="tiny">'+available.length+'/'+items.length+' متاح الآن</span></div></article>'}).join('')}catch(e){console.error(e);host.classList.add('hidden')}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load);else load();})();